#include <stdio.h>
#include <limits.h>

#define MAXN 105
#define INF 1000000000

int adj[MAXN][MAXN];
int dist[MAXN];
int visited[MAXN];

int main() {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            adj[i][j] = (i == j) ? 0 : INF;
        }
        dist[i] = INF;
        visited[i] = 0;
    }

    for (int i = 0; i < m; i++) {
        int u, v, c;
        scanf("%d %d %d", &u, &v, &c);
        if (c < adj[u][v]) {
            adj[u][v] = c;
            adj[v][u] = c;
        }
    }

    dist[1] = 0;

    for (int i = 1; i <= n; i++) {
        int u = -1;
        int min_d = INF;

        for (int j = 1; j <= n; j++) {
            if (!visited[j] && dist[j] < min_d) {
                min_d = dist[j];
                u = j;
            }
        }

        if (u == -1 || min_d == INF) break;

        visited[u] = 1;

        for (int v = 1; v <= n; v++) {
            if (!visited[v] && adj[u][v] < INF) {
                if (dist[u] + adj[u][v] < dist[v]) {
                    dist[v] = dist[u] + adj[u][v];
                }
            }
        }
    }

    printf("%d\n", dist[n]);

    return 0;
}
